const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    CrossAttentionCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0); // [B, M, K]
    const gert::Shape* y_shape = context->GetInputShape(1); // [B, N, K]

    uint32_t batch = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t m = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t k = static_cast<uint32_t>(x_shape->GetDim(2));
    uint32_t n = static_cast<uint32_t>(y_shape->GetDim(1));

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_batch(batch);
    tiling.set_m(m);
    tiling.set_k(k);
    tiling.set_n(n);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0; // no workspace
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // Output z has the same shape as input x: [B, M, K]
    const gert::Shape* x_shape = context->GetInputShape(0);
    gert::Shape* z_shape = context->GetOutputShape(0);
    *z_shape = *x_shape;
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
